#!/usr/bin/env python3
"""Add the weekly low-9 confidence score to the low9 repo. Run in the repo folder."""
import base64, sys

def rep(path, old_b, new_b, tag):
    src = open(path, encoding="utf-8").read()
    old = base64.b64decode(old_b).decode(); new = base64.b64decode(new_b).decode()
    if new in src:
        print(f"  [skip] {path}: {tag} already applied"); return src, True
    if old not in src:
        print(f"  [FAIL] {path}: anchor not found for {tag}"); return src, False
    print(f"  [ok]   {path}: {tag}")
    return src.replace(old, new, 1), True

# ---- scanner: plain-text edits ----
S = open("low9_scanner.py", encoding="utf-8").read()
sc_edits = [
 ("statistics import",
  "import sys, time, json, csv, io, re, argparse, urllib.request\n",
  "import sys, time, json, csv, io, re, argparse, urllib.request, statistics\n"),
 ("hit_features()",
  "def record_backtest(closes, tf, side, horizons, bt):",
  "def hit_features(dcloses, wcloses):\n"
  "    rets = [(dcloses[i]-dcloses[i-1])/dcloses[i-1] for i in range(1, len(dcloses)) if dcloses[i-1] > 0]\n"
  "    vol = round(statistics.pstdev(rets) * (252 ** 0.5), 4) if len(rets) >= 20 else None\n"
  "    depth = round((wcloses[-1]-wcloses[-10])/wcloses[-10], 4) if len(wcloses) >= 11 and wcloses[-10] > 0 else None\n"
  "    ma = sum(wcloses[-40:]) / len(wcloses[-40:]) if wcloses else None\n"
  "    above = bool(wcloses[-1] > ma) if ma else None\n"
  "    return vol, depth, above\n\n"
  "def record_backtest(closes, tf, side, horizons, bt):"),
 ("features in hit",
  "            if max(cur.values()) >= 7:\n"
  "                hits.append(dict(sym=sym, name=name, sector=sector,\n"
  "                                 price=round(dcloses[-1], 2), **cur))",
  "            if max(cur.values()) >= 7:\n"
  "                vol, depth, above_ma = hit_features(dcloses, wcloses)\n"
  "                hits.append(dict(sym=sym, name=name, sector=sector,\n"
  "                                 price=round(dcloses[-1], 2), vol=vol, depth=depth,\n"
  "                                 above_ma=above_ma, **cur))"),
]
ok = True
for tag, old, new in sc_edits:
    if new in S: print(f"  [skip] low9_scanner.py: {tag}"); continue
    if old not in S: print(f"  [FAIL] low9_scanner.py: {tag}"); ok=False; break
    S = S.replace(old, new, 1); print(f"  [ok]   low9_scanner.py: {tag}")
if ok: open("low9_scanner.py","w",encoding="utf-8").write(S)

# ---- dashboard: base64 region edits ----
PAIRS = [['', ''], ['', ''], ['LmJhZGdlIC5wbHVze3tmb250LXdlaWdodDo0MDA7Zm9udC1zaXplOjExcHg7b3BhY2l0eTouODV9fQo=', ''], ['PGRpdiBjbGFzcz0ibm90ZSI+e3BlX25vdGV9PGI+SG93IHRvIHJlYWQgdGhpczo8L2I+', '']]
D = "low9_dashboard_builder.py"
src = open(D, encoding="utf-8").read()
for i,(ob,nb) in enumerate(PAIRS):
    old = base64.b64decode(ob).decode(); new = base64.b64decode(nb).decode()
    if new in src: print(f"  [skip] {D}: region {i}"); continue
    if old not in src: print(f"  [FAIL] {D}: region {i} anchor missing"); ok=False; break
    src = src.replace(old, new, 1); print(f"  [ok]   {D}: region {i}")
if ok: open(D,"w",encoding="utf-8").write(src)

open("model.json","wb").write(base64.b64decode(''))
print("  [ok]   wrote model.json")
open("low9_score.py","wb").write(base64.b64decode(''))
print("  [ok]   wrote low9_score.py")
print("\nDONE. Next: git add -f model.json && git add -A && git commit -m 'confidence score' && git push")
